/*
 * tlv320aic3204.c
 */

typedef struct {
  int target_level;
  int gain_hysteresis;
  int attack;
  int attack_scale;
  int decay;
  int decay_scale;
  int maximum_gain;
} tlv320aic3204_agc_config_t;

