typedef struct {
    enum { CHANNEL, FREQ, VOLUME, MOD, AGC, RFGAIN, AGC_MAXGAIN, CWTONE, IQBAL,
         SPDISP, WFDISP, MODE_MAX } mode;
	int8_t volume;
    uint8_t channel;

    uint32_t freq;
	modulation_t modulation;
