    tlv320aic3204_stop();

    // then stop I2S
    i2sStopExchange(&I2SD2);
    // wait a second (not enough in 20ms)
    chThdSleepMilliseconds(40);
    // re-prepare I2S
    i2sStartExchange(&I2SD2);

    // enable WCLK,BCLK
    tlv320aic3204_set_fs(fs);
  }
}

